'use strict';
/* public/js/50-tents.js -- entering/leaving tents, bunks, sleeping. Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- tent interiors: entering, leaving, bunks ---------- */
function inTent(){return S.tent!=null}
function enterTent(ti){
  if(S.ko||uiOpen()||inTent())return;
  const t=TENTS[ti];S.tent=ti;S.tentBack={x:t.x,z:t.z-t.hd-1.3};S.inBed=null;
  ROOM_MESHES[ti].visible=true;
  ROOM_LIGHTS[ti].visible=true;
  P.x=t.x;P.z=t.z-t.roomD+2.6;P.yaw=Math.PI;P.fa=0;P.y=TENT_FLOOR_Y; // enter at the marked south door, facing the room
  P.vy=0;P.kx=P.kz=0;P.crouch=false;digHeld=false;
  logEv('tentEnter',{tent:ti,name:t.name,x:+P.x.toFixed(1),z:+P.z.toFixed(1)});
  toast(`You enter ${t.name}.${t.crew?' The cards table is on the right.':''} Press E at the door to leave.`,'',3200);
}
function exitTent(){
  if(!inTent())return;
  const ti=S.tent,t=TENTS[S.tent],wasBed=S.inBed!=null;S.tent=null;S.inBed=null;digHeld=false;
  ROOM_MESHES[ti].visible=false;
  ROOM_LIGHTS[ti].visible=false;
  P.x=S.tentBack.x;P.z=S.tentBack.z;P.y=groundAt(P.x,P.z);P.vy=0;
  if(wasBed&&online())wsSend({t:'sleep',on:false});
  logEv('tentExit',{tent:ti,name:t.name,x:+P.x.toFixed(1),z:+P.z.toFixed(1)});
  toast(`You step back outside ${t.name}.`,'',2200);
}
function toggleBunk(bi){
  if(!inTent())return;
  if(S.inBed===bi){S.inBed=null;if(online())wsSend({t:'sleep',on:false});toast('You get up.','',1600);return}
  const b=BUNKS[bi];if(b.tent!==S.tent)return;   // not one of this tent's own bunks
  S.inBed=bi;P.x=b.x;P.z=b.z;digHeld=false;
  if(online()){wsSend({t:'sleep',on:true});toast('You lie down. Everyone in camp needs to be asleep for the night to pass.','',3600)}
  else if(clockT()>=DAYMS){jumpTo(tAtHour(6));toast('You get some sleep. Morning already.','good',3200);S.inBed=null}
  else toast('You lie down and rest. Nothing to skip yet - it\'s still daytime.','',3200);
}
function reveal(who){if(S.revealed)return;S.revealed=true;flags.visible=true;if(who!=='You')toast(`${who} gave the gold tube to the Warden. Red flags mark the search area.`,'gold',6000)}

/* shop */
const SHOP=[
  {id:'spade',name:'Sharpened spade',desc:'Every scoop goes about 70% deeper.',cost:45},
  {id:'long',name:'Long-handled shovel',desc:'Dig down to 8 feet instead of 5.',cost:110},
  {id:'detector',name:'Metal detector',desc:'Beeps faster when you stand over buried things. Range 7 m.',cost:70},
  {id:'canteen',name:'Big canteen',desc:'Holds 60% more water.',cost:30},
  {id:'bigsack',name:'Bigger sack',desc:'Carry 3 more finds before you have to walk back.',cost:60},
  {id:'rope',name:'Rope ladder',desc:'Climb out of deep holes in 1.5 seconds instead of 8.',cost:35},
  {id:'onion',name:'Raw onion',desc:'Eat with Q. Lizards won\'t come near you for 45 seconds.',cost:8,stack:'onions'},
  {id:'battery',name:'Flashlight batteries',desc:'Fills your flashlight (L). It lasts about 3 minutes.',cost:6,stack:'batt'},
];
let shopOpen=false;
function openShop(){shopOpen=true;releaseLock();$('#shop').hidden=false;renderShop();setTimeout(()=>$('#shopClose').focus(),30)}
function closeShop(){shopOpen=false;$('#shop').hidden=true}
function renderShop(){
  $('#shopSeeds').textContent=S.seeds;const list=$('#shopList');list.textContent='';
  for(const it of SHOP){
    const row=document.createElement('div');row.className='shoprow';
    const b=document.createElement('b');b.textContent=it.name;const d=document.createElement('span');d.textContent=it.desc+(it.stack==='onions'?` You have ${S.onions}.`:it.stack==='batt'?` Battery: ${Math.round(S.batt)}%.`:'');
    const btn=document.createElement('button');const owned=!it.stack&&S.up[it.id];
    btn.textContent=owned?'Owned':`${it.cost} seeds`;btn.disabled=owned||S.seeds<it.cost;btn.id='buy-'+it.id;
    btn.onclick=()=>{if(S.seeds<it.cost)return;S.seeds-=it.cost;if(it.stack==='onions')S.onions++;else if(it.stack==='batt')S.batt=100;else S.up[it.id]=true;if(it.id==='canteen')S.water=waterMax();sfx.coin();renderShop();toast(`Bought: ${it.name}`,'good',2000)};
    row.append(b,d,btn);list.appendChild(row);
  }
}
$('#shopClose').onclick=closeShop;

/* KO */
function knockOut(title,text){
  if(S.ko)return;S.hp=0;P.kx=P.kz=0;S.ko=othersOnline()?25:4;digHeld=false;S.carry=null;S.light=false;
  logEv('ko',{title,text,x:+P.x.toFixed(1),z:+P.z.toFixed(1)});
  twSt=0;twStT=0;me.g.rotation.z=0;   // clears any twister suck/tumble/lie state so it can't fight the KO pose or get stuck
  const lost=S.sack.length;dropBag();
  $('#koTitle').textContent=title;$('#koText').textContent=text+(lost?' Your sack fell where you went down. Anyone can pick it up.':'');$('#ko').hidden=false;
}
function respawn(){if(inTent())exitTent();S.ko=0;S.hp=HP_MAX;S.hurtT=99;S.respawnAt=performance.now();$('#ko').hidden=true;P.x=0;P.z=39;P.y=groundAt(0,39);P.vy=0;P.kx=P.kz=0;P.fa=Math.PI;P.yaw=0;S.water=waterMax();twSt=0;twStT=0;me.g.rotation.set(0,0,0)}

/* win */
function triggerWin(who,mine){
  if(S.won)return;S.won=true;
  rain.visible=true;if(rainGain)rainGain.gain.setTargetAtTime(0.18,AC.currentTime,2);
  $('#winText').textContent=mine?'You dug up Stanley Yelnats\'s suitcase. Kissin\' Kate\'s treasure has been in the ground for over a hundred years. +500 seeds.':`${who} dug up Stanley Yelnats's suitcase. Kissin' Kate's treasure has been in the ground for over a hundred years.`;
  if(mine){S.seeds+=500;wsSend({t:'win'})}
  setTimeout(()=>{$('#win').hidden=false;releaseLock()},1600);
}
$('#winClose').onclick=()=>{$('#win').hidden=true};
